async function readSenders(c) {
 const rows=[];let total,last;
 for(let page=1;page<=100;page++){
  const r=await this.helpers.httpRequest({method:'GET',url:c.baseUrl+'/api/campaigns/'+c.campaignId+'/sender-emails',qs:{page},headers:{Authorization:'[REDACTED]'+c.apiKey},json:true,timeout:25000});
  const m=r.meta;
  if(!Array.isArray(r.data)||!m||Number(m.current_page)!==page||!Number.isInteger(Number(m.total))||!Number.isInteger(Number(m.last_page))||Number(m.last_page)<1||Number(m.last_page)>100)throw new Error('Sender pagination could not be verified.');
  if(page===1){total=Number(m.total);last=Number(m.last_page);}
  if(total!==Number(m.total)||last!==Number(m.last_page))throw new Error('Senders changed during verification.');
  rows.push(...r.data.map(x=>({id:String(x.id),status:String(x.status).toLowerCase()})));
  if(page===last){
   if(rows.length!==total||new Set(rows.map(x=>x.id)).size!==total)throw new Error('Sender counts did not reconcile.');
   return rows;
  }
 }
 throw new Error('Sender page limit exceeded.');
}
async function verifySenders(c) {
 const expected=(c.senderEmailIds||[]).map(String).sort();
 if(!expected.length||new Set(expected).size!==expected.length||expected.some(id=>!/^\d+$/.test(id)||Number(id)<1))throw new Error('A unique selected sender set is required.');
 const actual=await readSenders.call(this,c);
 if(JSON.stringify(actual.map(x=>x.id).sort())!==JSON.stringify(expected))throw new Error('EmailBison senders do not exactly match the Airtable selection.');
 if(actual.some(x=>x.status!=='connected'))throw new Error('A selected sender is not connected.');
 return expected;
}

